"""Hippie Station Security and the Brig, generated by the node graph (forge/proc), the third department through it.

    python tools/mapforge/blueprints/security_v1.py            # run the graph, one picture per node
    python tools/mapforge/mapforge.py build blueprints/security_v1.py
    MAPFORGE_SEED=3 python tools/mapforge/mapforge.py build blueprints/security_v1.py

What the outline fixes: the cells sit behind the windows and blast doors that face the fore hallway, the front desk
behind its shutters, the cycled entry airlocks; the brig corridor with its doors to processing, the courtroom and
the perma wing; the pod airlock and MULE flaps east of the briefing room; the HoS's space shutters. The rest is two
blocks the solver cuts per seed: the warden's block (warden on the corridor, the armory behind it, an interview
room) and the officers' block (briefing on the corridor, the gear room and the HoS behind it).
"""
import os
import random
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, ".."))
from forge.proc import geo as G  # noqa: E402
from forge.proc import shell, furnish, emit, solve  # noqa: E402
from assets import security as assets  # noqa: E402
from forge.proc.shell import X, Y, door, glass, keep  # noqa: E402

NAME = "security_v1"
ROOT = os.path.abspath(os.path.join(HERE, "..", "..", ".."))
BASE_MAP = os.path.join(ROOT, "_maps", "map_files", "HippieStation", "hippiestation.dmm")
BBOX = (98, 164, 138, 186)
AREAS = ("/area/security/brig", "/area/security/warden", "/area/ai_monitored/security/armory", "/area/security/main",
         "/area/crew_quarters/heads/hos")

# ---------------------------------------------------------------- inputs: what the outline fixes
FRONT = [(x, 165) for x in list(range(103, 106)) + list(range(107, 110)) + list(range(111, 114)) + [115, 116, 117]]
ENTRY = [(118, 165), (119, 165)]                     # the cycled public entrance from the fore hallway
PROCESSING = (98, 169)
COURT = (124, 170)
PERMA = [(108, 176), (109, 176)]                     # the perma wing's blast doors
FLAPS = (133, 175)                                   # the MULE windoor onto the delivery flaps
SPACE = [(127, 185), (128, 185), (129, 185), (121, 185), (123, 185), (132, 180), (133, 180)]
ANNEX = [(x, y) for x in range(134, 139) for y in range(175, 183)]     # the pod airlock, kept whole


def in_zone(a):
    return a in AREAS


PARAMS = dict(seed=1)

BRIG = "/area/security/brig"
MAIN = "/area/security/main"
FLOOR, DARKF = "/turf/open/floor/plasteel", "/turf/open/floor/plasteel/dark"
ROOM_TABLE = {
    "brighall": dict(area=BRIG, floor=FLOOR, name="Brig", hall=True, label="BRIG"),
    "evidence": dict(area=BRIG, floor=DARKF, name="Evidence Storage", label="EVID"),
    "cell1": dict(area=BRIG, floor=DARKF, name="Cell 1", label="C1"),
    "cell2": dict(area=BRIG, floor=DARKF, name="Cell 2", label="C2"),
    "cell3": dict(area=BRIG, floor=DARKF, name="Cell 3", label="C3"),
    "cell4": dict(area=BRIG, floor=DARKF, name="Cell 4", label="C4"),
    "frontdesk": dict(area=BRIG, floor=DARKF, name="Brig Front Desk", label="DESK"),
    "entry": dict(area=BRIG, floor=FLOOR, name="Brig Entry", label="IN"),
    "infirm": dict(area=BRIG, floor="/turf/open/floor/plasteel/white", name="Brig Infirmary", label="INF"),
    "interro": dict(area=BRIG, floor=DARKF, name="Interrogation", label="INT"),
    "warden": dict(area="/area/security/warden", floor=DARKF, name="Warden's Office", label="WARDEN"),
    "armory": dict(area="/area/ai_monitored/security/armory", floor=DARKF, name="Armory", label="ARMORY"),
    "main": dict(area=MAIN, floor=FLOOR, name="Security Briefing", newscaster=True, label="BRIEF"),
    "gear": dict(area=MAIN, floor=FLOOR, name="Security Gear Room", label="GEAR"),
    "dock": dict(area=MAIN, floor=FLOOR, name="Security Dock", label="DOCK"),
    "hos": dict(area="/area/crew_quarters/heads/hos", floor=DARKF, name="Head of Security's Office", label="HOS"),
}

WBLOCK = (111, 173, 118, 182)       # the warden's block, behind the corridor's north wall
NBLOCK = (120, 173, 130, 184)       # the officers' block


def authored(P):
    return {
        "W": Y((5, "armory"), (1.0, X((3, "interro"), (1.0, "warden")))),
        "N": Y((6, X((5, "gear"), (1.0, "hos"))), (1.0, "main")),
    }


def plans(P, fill=None):
    f = fill or authored(P)
    return [
        ((99, 165, 101, 167), "evidence"),
        ((103, 166, 105, 167), "cell1"),
        ((107, 166, 109, 167), "cell2"),
        ((111, 166, 113, 167), "cell3"),
        ((115, 166, 116, 167), "frontdesk"),
        ((118, 166, 119, 167), "entry"),
        ((121, 166, 123, 167), "cell4"),
        ((99, 169, 123, 170), "brighall"),
        ((108, 171, 123, 171), "brighall"),
        ((108, 172, 109, 175), "brighall"),          # the way to the perma wing
        ((104, 172, 106, 175), "infirm"),
        (WBLOCK, f["W"]),
        (NBLOCK, f["N"]),
        ((132, 173, 133, 179), "dock"),
    ]


def program(P):
    """The two free blocks as a room list. The warden must sit on the corridor where the desk window is; the HoS
    where the space shutters are; the briefing room on the corridor (its door) and on the dock."""
    blocks = [
        solve.Block("W", WBLOCK, {"s": ("hall", WBLOCK[0], WBLOCK[2]), "w": ("hall", 173, 175)}),
        solve.Block("N", NBLOCK, {"s": ("hall", 120, 123), "e": ("dock", 173, 179), "n": ("space", 127, 129)}),
    ]
    W = solve.Want
    wants = [
        W("warden", 24, min=(3, 4), front=("hall",), anchors=[(114, 173)]),
        W("armory", 32, min=(4, 5), front=()),
        W("interro", 9, min=(3, 3), front=("hall",), fixed={"w": 3}),
        W("main", 40, min=(4, 5), front=("hall", "dock")),
        W("gear", 28, min=(4, 5), front=(), near=("main",)),
        W("hos", 28, min=(4, 5), front=(), anchors=[(128, 184)]),
    ]
    return blocks, wants


LINK_PAIRS = [("armory", "warden"), ("gear", "main"), ("hos", "main")]


def seeded(seed, tries=8):
    last = None
    for t in range(tries):
        P = dict(PARAMS)
        blocks, wants = program(P)
        trees, rects, report = solve.solve(blocks, wants, LINK_PAIRS, seed="%s.%d" % (seed, t), ratio=(0.5, 1.6),
                                           fill=True, fixed={"warden": "W", "armory": "W", "interro": "W",
                                                             "main": "N", "gear": "N", "hos": "N"})
        if trees is None:
            break
        g = graph(fill=trees)
        geo = g.run()
        geo.notes[:0] = report + ["seed %s: try %d, %d problems" % (seed, t, len(geo.problems))]
        last = (g, geo)
        if not geo.problems:
            break
    return last


SEC = dict(kind="security", access="63")
CYCLE = "/obj/effect/mapping_helpers/airlock/cyclelink_helper"
LINKS = [
    keep(PROCESSING, "brighall"), keep(COURT, "brighall"), keep(PERMA[0], "brighall"), keep(PERMA[1], "brighall"),
    keep(ENTRY[0], "entry"), keep(ENTRY[1], "entry"), keep(FLAPS, "dock"),
    # the public: through the cycled entry, or served at the desk
    door("entry", "brighall", wide=2, name="Brig", glass=True, vars={"id_tag": "innerbrig"},
         extra=[(CYCLE, {"dir": 2})], **SEC),
    door("frontdesk", "entry", type="brigdesk", id="briggate", name="Brig Desk", access="1"),
    door("frontdesk", "brighall", name="Brig Front Desk", glass=True, **SEC),
    # cells: a secure windoor the timer works, glass either side so the corridor sees in
    door("cell1", "brighall", type="cell", id="Cell 1", name="Cell 1"), glass("cell1", "brighall"),
    door("cell2", "brighall", type="cell", id="Cell 2", name="Cell 2"), glass("cell2", "brighall"),
    door("cell3", "brighall", type="cell", id="Cell 3", name="Cell 3"), glass("cell3", "brighall"),
    door("cell4", "brighall", type="cell", id="Cell 4", name="Cell 4"), glass("cell4", "brighall"),
    door("evidence", "brighall", name="Evidence Storage", kind="security", access="1"),
    door("infirm", "brighall", name="Brig Infirmary", glass=True, **SEC), glass("infirm", "brighall"),
    door("interro", "brighall", name="Interrogation", **SEC),
    # the warden: a desk window onto the corridor, the armory only through the office
    door("warden", "brighall", type="brigdesk", id="wardenshutter", name="Warden's Desk", access="3"),
    door("warden", "brighall", at=0.9, name="Warden's Office", glass=True, kind="security", access="3"),
    glass("warden", "brighall"),
    door("armory", "warden", name="Armory", kind="security", access="3"),
    # the officers
    door("main", "brighall", name="Security", **SEC),
    door("main", "dock", name="Security Dock", glass=True, **SEC),
    door("gear", "main", name="Gear Room", glass=True, **SEC),
    door("hos", "main", name="Head of Security", kind="command", glass=True, access="58"),
]


SEED = int(os.environ.get("MAPFORGE_SEED", "1"))
if SEED != 1:
    PARAMS["seed"] = SEED
    NAME += "_s%d" % SEED


def graph(fill=None, **over):
    P = dict(PARAMS)
    P.update(over)
    g = G.Graph(NAME, **P)
    g.add("outline", shell.outline, view="kind", base=BASE_MAP, bbox=BBOX, in_zone=in_zone,
          keep=FRONT + SPACE, gates=ENTRY + [PROCESSING, COURT, FLAPS] + PERMA, inside=ANNEX)
    g.add("slice", shell.slice_rooms, view="rooms", plans=plans(P, fill), rooms=ROOM_TABLE)
    g.add("tidy", shell.tidy, view="rooms")
    g.add("openings", shell.openings, view="rooms", links=LINKS)
    g.add("fields", shell.fields, view="fields")
    g.add("furnish", furnish.furnish, view="items", assets=assets.ASSETS)
    return g


_graph, _geo = seeded(SEED) if SEED != 1 else (graph(), None)
_geo = _geo or _graph.run()
globals().update(emit.blueprint(_geo, NAME, extra=dict(STYLE="meta", DISPOSALS="route", DRESS_HALL_FRONT=True,
                                                       BASE=BASE_MAP)))


def main():
    g, geo = _graph, _geo
    out = os.path.join(ROOT, "data", "previews", "mapforge", "proc")
    paths = g.pictures(out, tile=20)
    G.sheet(paths, os.path.join(out, NAME + "_nodes.png"), cols=3)
    G.draw(geo, "items", os.path.join(out, NAME + "_furnish_big.png"), tile=30, title="furnish")
    for n in geo.notes:
        print(n)
    for p in geo.problems:
        print("PROBLEM", p)
    print("pictures:", os.path.relpath(os.path.join(out, NAME + "_nodes.png"), ROOT))


if __name__ == "__main__":
    main()
